'use strict';
// Presentation extension: existing impact logic, tasks and records stay authoritative.
const V25UI={day:null,metric:'wind'};
function v25Num(v){return typeof v==='number'&&Number.isFinite(v)?v:null}
function v25Value(v,unit=''){return v25Num(v)===null?'—':esc(String(v))+(unit?' '+esc(unit):'')}
function v25WeatherName(c){return v20En()?v18English(v12WeatherName(c)):v12WeatherName(c)}
function v25WeatherIcon(c){if(c==null)return '◌';if(c<=1)return '☀';if(c<=3)return '☁';if(c>=95)return 'ϟ';if(c>=51&&c<=82)return '☂';return '◌'}
function v25Days(w){const d=w?.daily;if(!Array.isArray(d?.time))return [];return d.time.slice(0,7).map((t,i)=>({t,code:d.weather_code?.[i],min:d.temperature_2m_min?.[i],max:d.temperature_2m_max?.[i],rain:d.precipitation_sum?.[i],prob:d.precipitation_probability_max?.[i]}))}
function v25SelectedDay(w){const days=v25Days(w);return days.some(d=>d.t===V25UI.day)?V25UI.day:days[0]?.t||null}
function v25Hours(w,day=null){const h=w?.hourly;if(!Array.isArray(h?.time))return [];return h.time.map((t,i)=>({t,temp:h.temperature_2m?.[i],feel:h.apparent_temperature?.[i],rain:h.precipitation?.[i],prob:h.precipitation_probability?.[i],weather:h.weather_code?.[i],humidity:h.relative_humidity_2m?.[i],wind:h.wind_speed_10m?.[i],gust:h.wind_gusts_10m?.[i]})).filter(r=>day?r.t.slice(0,10)===day:r.t>=(w.current?.time||'')).slice(0,24)}
function v25Daily(w){const ds=v25Days(w);if(!ds.length)return `<p class="muted">${v20Text('这份查询没有七天预报；刷新现在天气后可查看。旧查询保留原数据。','This query has no seven-day forecast. Refresh current weather to fetch it; saved queries retain their original data.')}</p>`;const selected=v25SelectedDay(w);return `<div class="v25weekhead"><h3>${v20Text('七日天气（本次预报）','Seven-day weather (this forecast)')}</h3><small>${v20Text('选一天查看逐小时趋势 · 北京时间','Select a day for hourly trends · Beijing time')}</small></div><div class="v25days">${ds.map(d=>`<button type="button" class="v25day ${selected===d.t?'active':''}" data-v25="day" data-value="${esc(d.t)}" aria-pressed="${selected===d.t}"><b>${esc(d.t.slice(5).replace('-','/'))}</b><span class="v25symbol" aria-hidden="true">${v25WeatherIcon(d.code)}</span><span>${esc(v25WeatherName(d.code))}</span><strong>${v25Value(d.min)} / ${v25Value(d.max)} °C</strong><small>${v20Text('日降水','Daily rain')} ${v25Value(d.rain,'mm')}</small><small>${v20Text('小时降水概率最大值','Max hourly rain probability')} ${v25Value(d.prob,'%')}</small></button>`).join('')}</div>`}
function v25Chart(rows,keys,title,unit,colors=['#159b8e','#6485ca'],bars=false){const vals=rows.flatMap(r=>keys.map(k=>v25Num(r[k]))).filter(v=>v!==null);if(!vals.length)return `<div class="v25chartempty">${esc(title)} · ${v20Text('数据未取得','Data unavailable')}</div>`;const lo=unit==='°C'?Math.floor(Math.min(...vals)-1):0,hi=unit==='%'?100:Math.max(lo+1,Math.ceil(Math.max(...vals)+(unit==='°C'?1:0)));const x=i=>54+i*632/Math.max(1,rows.length-1),y=v=>178-(v-lo)/(hi-lo)*130;let grid='';for(let j=0;j<=4;j++){const v=lo+(hi-lo)*j/4;grid+=`<line x1="54" x2="686" y1="${y(v)}" y2="${y(v)}" stroke="#dfe9ee"/><text x="45" y="${y(v)+4}" text-anchor="end" font-size="11" fill="#53697d">${Number(v.toFixed(1))}</text>`}let marks='';keys.forEach((k,j)=>{let path='',prev=false;rows.forEach((r,i)=>{const v=v25Num(r[k]);if(v===null){prev=false;return}if(bars){if(v>0)marks+=`<rect x="${x(i)-7}" y="${y(v)}" width="14" height="${178-y(v)}" fill="${colors[j]}"><title>${esc(r.t)}: ${v} ${unit}</title></rect>`}else{path+=(prev?' L':' M')+x(i)+' '+y(v);prev=true;marks+=`<circle cx="${x(i)}" cy="${y(v)}" r="2.5" fill="${colors[j]}"><title>${esc(r.t)}: ${v} ${unit}</title></circle>`}});if(!bars)marks+=`<path d="${path}" fill="none" stroke="${colors[j]}" stroke-width="2.5"/>`});const weatherMarks=keys.includes('temp')?rows.map((r,i)=>i%4===0||i===rows.length-1?`<text x="${x(i)}" y="43" text-anchor="middle" font-size="9" fill="#53697d"><title>${esc(v25WeatherName(r.weather))}</title>${esc(v25WeatherName(r.weather).slice(0,v20En()?10:6))}</text>`:'').join(''):'';const labels=rows.map((r,i)=>i%4===0||i===rows.length-1?`<text x="${x(i)}" y="199" text-anchor="middle" font-size="11" fill="#53697d">${esc(r.t.slice(11,16))}</text>`:'').join('');return `<svg class="v25chart" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 720 225" role="img" aria-label="${esc(title+' '+unit)}"><rect width="720" height="225" rx="10" fill="#fff"/><text x="54" y="25" fill="#334e68" font-size="13">${esc(title)} (${esc(unit)})</text>${grid}${marks}${weatherMarks}${labels}${bars&&vals.every(v=>v===0)?`<text x="360" y="110" text-anchor="middle" fill="#53697d" font-size="13">${v20Text('已取得时段降水均为 0 mm','Available hours: 0 mm rain')}</text>`:''}<text x="686" y="218" text-anchor="end" font-size="10" fill="#53697d">${v20Text('时间（北京时间）','Time (Beijing)')}</text></svg>`}
function v25Trends(w,day=null){const rows=v25Hours(w,day);if(!rows.length)return `<p>${v20Text('逐小时资料未取得。','Hourly data unavailable.')}</p>`;const metric=['wind','humidity','prob'].includes(V25UI.metric)?V25UI.metric:'wind';const extra=metric==='wind'?v25Chart(rows,['wind','gust'],v20Text('风速 / 阵风','Wind / gusts'),'m/s'):v25Chart(rows,[metric],metric==='humidity'?v20Text('相对湿度','Relative humidity'):v20Text('小时降水概率','Hourly rain probability'),'%');return `<div class="v25trends"><div class="v25chartgrid"><section><h4>${v20Text('气温与体感','Temperature and feels-like')}</h4>${v25Chart(rows,['temp','feel'],v20Text('气温 / 体感温度','Temperature / feels-like'),'°C')}<small>${v20Text('青绿：气温 · 蓝色：体感','Teal: temperature · Blue: feels-like')}</small></section><section><h4>${v20Text('逐小时降雨','Hourly precipitation')}</h4>${v25Chart(rows,['rain'],v20Text('小时累计降水','Hourly precipitation'),'mm',['#6485ca'],true)}<small>${v20Text('雨量统计降水；道路水深另受地形和排水影响。','Rainfall measures precipitation; terrain and drainage also affect street water depth.')}</small></section></div><div class="v25tabs" role="group" aria-label="${v20Text('天气图表','Weather charts')}">${[['wind','风速与阵风','Wind and gusts'],['humidity','湿度','Humidity'],['prob','降水概率','Rain probability']].map(([key,zh,en])=>`<button type="button" data-v25="metric" data-value="${key}" aria-pressed="${metric===key}" class="${metric===key?'active':''}">${v20Text(zh,en)}</button>`).join('')}</div>${extra}${metric==='wind'?`<small>${v20Text('青绿：风速 · 蓝色：阵风','Teal: wind · Blue: gusts')}</small>`:''}<details><summary>${v20Text('逐小时数值与单位','Hourly values and units')}</summary><div class="tablewrap"><table><tr>${[v20Text('时间','Time'),'°C',v20Text('体感 °C','Feels-like °C'),'mm',v20Text('降水概率 %','Rain probability %'),v20Text('湿度 %','Humidity %'),v20Text('风速 m/s','Wind m/s'),v20Text('阵风 m/s','Gust m/s')].map(t=>`<th>${t}</th>`).join('')}</tr>${rows.map(r=>`<tr><td>${esc(r.t.replace('T',' '))}</td>${['temp','feel','rain','prob','humidity','wind','gust'].map(k=>`<td>${v25Value(r[k])}</td>`).join('')}</tr>`).join('')}</table></div></details></div>`}
const v25TrendBase=v5Trend;
v5Trend=function(){if(V2.mode==='history'||!V2.weather?.hourly)return v25TrendBase();return v25Trends(V2.weather,v25SelectedDay(V2.weather))};
function v25WeatherSummary(w){const c=w.current||{},units=w.current_units||{};const cards=[['apparent_temperature','体感温度','Feels-like','°C'],['relative_humidity_2m','相对湿度','Relative humidity','%'],['wind_gusts_10m','阵风','Wind gusts','m/s'],['wind_direction_10m','风向（北为0°）','Wind direction (N=0°)','°'],['surface_pressure','地面气压','Surface pressure','hPa'],['cloud_cover','云量','Cloud cover','%']];return `<section class="v25weatherextra"><div class="v25weatherhead"><span class="v25symbol" aria-hidden="true">${v25WeatherIcon(c.weather_code)}</span><div><b>${esc(v25WeatherName(c.weather_code))} · ${esc(w.place||V5.weatherPlace)}</b><small>${v20Text('模型天气 · 非现场观测','Model weather · Not field observations')} · ${esc(c.time?dateText(c.time):'—')}</small></div></div><div class="v25metrics">${cards.map(([k,zh,en,u])=>`<div><small>${v20Text(zh,en)}</small><b>${v25Value(c[k],units[k]||u)}</b></div>`).join('')}</div>${v25Daily(w)}<small>${v20Text('日降水为全天累计；日卡概率为逐小时降水概率最大值，不是三小时强降雨概率。缺测显示“—”。','Daily rain is a day total; daily cards show maximum hourly rain probability, not three-hour heavy-rain probability. Missing values appear as “—”.')}</small></section>`}
const v25WeatherBase=v8Weather;
v8Weather=function(){let h=v25WeatherBase();if(V2.mode==='history'||!V2.weather?.current)return h;h=h.replace('展开24小时趋势与数据表',v20Text('展开选中日期的趋势与数据表','Selected-day trends and values'));const marker='<details class="v8weatherdetails">';const extra=v25WeatherSummary(V2.weather);return h.includes(marker)?h.replace(marker,extra+'<details class="v8weatherdetails"'+(V25UI.day?' open':'')+'>'):h+extra};
const v25RainBase=v18RainPanel;
v18RainPanel=function(p){const h=v25RainBase(p),r=v18RainResult(p);const valid=Number.isFinite(r.percent)&&Number.isFinite(r.n)&&r.n>0;const v=valid?Math.min(100,Math.max(0,r.percent)):0;const graph=`<div class="v25probability"><div class="v25probhead"><span>${v20Text('三小时强降雨 · 模型比例','Three-hour heavy rain · Ensemble share')}</span><b>${valid?v.toFixed(1)+'%':'—'}</b></div><div class="v25probtrack" ${valid?`role="meter" aria-label="${v20Text('强降雨概率','Heavy-rain probability')}" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${v}"`:''}><span style="width:${v}%"></span></div><div class="v25probscale"><span>0%</span><span>50%</span><span>100%</span></div><small>${valid?v20Text(`达标 ${r.count} / 有效 ${r.n} 个成员；不是积水或事故概率。`,`Threshold met by ${r.count} / ${r.n} valid members; not flooding or accident probability.`):v20Text('缺少有效资料，不显示概率。','No valid data; no probability is shown.')}</small></div>`;return h.replace('<details>',graph+'<details>')};
function v25ImpactPicture(p){const a=v20Impact(p),restricted=a.level==='red',unknown=a.level==='gray';const col=restricted?'#b74444':unknown?'#65788c':'#b87421';const related=vRelated(p),hazards=vRisks(p),reports=vFeedback(p),r=v18RainResult(p);return `<div class="v25impactpicture"><svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 240 96" role="img" aria-label="${esc(a.title)}"><rect width="240" height="96" rx="12" fill="${restricted?'#fff1f1':unknown?'#f1f5f8':'#fff8e9'}"/><path d="M15 68H225" stroke="#a1b0bc" stroke-width="5"/><rect x="25" y="30" width="30" height="36" rx="3" fill="#b7c9d6"/><rect x="185" y="22" width="30" height="44" rx="3" fill="#b7c9d6"/><path d="M63 65H176" stroke="${col}" stroke-width="3" stroke-dasharray="5 5"/><circle cx="120" cy="44" r="23" fill="white" stroke="${col}" stroke-width="3"/><text x="120" y="53" text-anchor="middle" font-size="28" fill="${col}">${restricted?'×':unknown?'?':'!'}</text></svg><div><small>${v20Text('出行影响示意 · 不表示水深','Travel impact illustration · No depth estimate')}</small><div class="v25evidencechips"><span>${v20Text('公告','Notices')} ${related.length}</span><span>${v20Text('长期隐患','Long-term hazards')} ${hazards.length}</span><span>${v20Text('现场线索','Reports')} ${reports.length}</span><span>${v20Text('强降雨模型','Rain model')} ${r.n?v25Value(r.percent?.toFixed?Number(r.percent.toFixed(1)):r.percent,'%'):'—'}</span></div><small>${v20Text('条数表示关联资料数量，不代表影响范围或危险分数。','Counts show related records, not affected area or a risk score.')}</small></div></div>`}
const v25DecisionsBase=v20DecisionPanel;
v20DecisionPanel=function(){let html=v25DecisionsBase();let i=0;const rows=v11Group();return html.replace(/(<article class="v20decision [^"]+">)/g,m=>m+v25ImpactPicture(rows[i++]))};
function v25About(){vDialog(v20Text('关于深雨知路','About RAINWISE'),`<div class="v25info"><div class="v25infotitle"><span>RAINWISE</span><h2>${v20Text('暴雨中的往返，让判断有依据。','Evidence for a round trip in heavy rain.')}</h2><p>${v20Text('面向深圳罗湖居民，聚焦罗湖—深圳人民医院的完整往返体验。就医家庭是演示情境，不是真实患者记录。','For residents of Luohu, Shenzhen, demonstrating a round trip to Shenzhen People’s Hospital. The family scenario is illustrative, not a patient record.')}</p></div><h3>${v20Text('为什么做','Purpose')}</h3><p>${v20Text('把分散的公告、天气与地点隐患放到两程中，帮助理解受影响区段、资料时间和判断依据。','Bring notices, weather and location hazards into both legs, showing affected sections, information times and evidence.')}</p><h3>${v20Text('AI 与数据','AI and data')}</h3><p>${v20Text('AI辅助整理离线公告样本；运行时使用显式规则关联。官方公告提供事件依据，Open-Meteo提供模型天气，OpenStreetMap提供地理参考。','AI-assisted offline notice extraction; explicit rules perform runtime matching. Official notices provide evidence, Open-Meteo supplies model weather, and OpenStreetMap provides geography.')}</p><h3>${v20Text('当前边界','Current limits')}</h3><p>${v20Text('尚未接入实时生成式AI、跨设备共享后台或正式维护账号认证。模型降雨概率不是积水或事故概率，图示不提供实测水深。任务记录保存在同一浏览器同一域名。','No live generative AI, cross-device backend or authenticated maintenance accounts. Rain probability is not flooding or accident probability; illustrations do not measure depth. Task records stay in this browser and origin.')}</p><h3>${v20Text('制作与下一步','Development and next steps')}</h3><p>${v20Text('独立参赛项目，围绕公开资料制作。下一阶段开展独立公告核对和用户理解对照，记录错误、遗漏及用时；尚未取得真实用户效果结论。','An independently developed competition project using public information. Next: independent notice checks and user comprehension comparisons, recording errors, omissions and time. No real-user outcome is claimed.')}</p><button data-v20="ai-evidence">${v20Text('查看 AI 样本与核对依据','Inspect AI samples and source checks')}</button></div>`)}
function v25Disasters(){vDialog(v20Text('灾害信息与演进方向','Disaster information and roadmap'),`<div class="v25info"><p>${v20Text('当前服务主线是罗湖暴雨与城市内涝出行。下面区分已提供的信息入口与未来能力。','The current focus is heavy rain and urban flooding in Luohu. Available information and future capabilities are distinguished below.')}</p><section class="v25disastercard"><h3>${v20Text('暴雨与城市内涝','Heavy rain and urban flooding')}</h3><span class="tag">${v20Text('当前可体验','Available')}</span><p>${v20Text('查看两程影响、模型降雨、历史公告与地点隐患；从具体来源核对资料。','Inspect both legs, model rain, historical notices and location hazards, with links to the evidence.')}</p></section><section class="v25disastercard"><h3>${v20Text('台风','Typhoons')}</h3><span class="tag gray">${v20Text('官方信息入口','Official information links')}</span><p>${v20Text('通过官方页面查看台风信息。本站风速与阵风属于模型天气参考；当前没有接入实时台风路径、登陆预测或台风专属影响评估。','Consult official pages for typhoon information. Wind and gusts here are model weather references; live tracks, landfall forecasts and typhoon-specific impact assessments are not integrated.')}</p><div class="v25links"><a href="https://typhoon.nmc.cn/" target="_blank" rel="noopener">${v20Text('中央气象台台风信息','NMC typhoon information')} ↗</a><a href="https://weather.sz.gov.cn/" target="_blank" rel="noopener">${v20Text('深圳气象官方发布','Shenzhen official weather')} ↗</a></div></section><section class="v25disastercard"><h3>${v20Text('地震','Earthquakes')}</h3><span class="tag gray">${v20Text('未来演进方向 · 尚未实现','Future direction · Not implemented')}</span><p>${v20Text('未来考虑增加来源明确的已发生地震信息、时间与距离说明及官方科普入口；尚未接入数据，不提供地震预测、预警或震后路线安全结论。','Future work may add sourced earthquake event information, time and distance explanations, and official educational links. No data feed, prediction, early warning or post-earthquake route safety assessment is provided.')}</p></section><p class="muted">${v20Text('实际行动以官方预警、管制与现场要求为准。','Follow official warnings, restrictions and on-site instructions.')}</p></div>`)}
const v25RenderBase=vRender;
vRender=function(){v25RenderBase();const foot=document.querySelector('.sidefoot')||document.querySelector('.topbar');if(foot&&!document.getElementById('v25-common-links')&&typeof foot.insertAdjacentHTML==='function')foot.insertAdjacentHTML('beforeend',`<div id="v25-common-links" class="v25common"><button type="button" data-v25="disasters">${v20Text('灾害','Disasters')}</button><button type="button" data-v25="about">${v20Text('关于我们','About us')}</button></div>`)};
document.addEventListener('click',e=>{const b=e.target.closest('[data-v25]');if(!b)return;e.preventDefault();e.stopImmediatePropagation();const a=b.dataset.v25;if(a==='about')return v25About();if(a==='disasters')return v25Disasters();if(a==='day'){if(!v25Days(V2.weather).some(d=>d.t===b.dataset.value))return;vDraft();V25UI.day=b.dataset.value;vRender()}if(a==='metric'&&['wind','humidity','prob'].includes(b.dataset.value)){vDraft();V25UI.metric=b.dataset.value;vRender()}},true);
// Exports use the original snapshot. No new request is made for missing old fields.
const v25PartsBase=v11WeatherParts;
v11WeatherParts=function(s,c){const parts=v25PartsBase(s,c);if(c.data&&s.mode!=='history'&&s.weather?.current){const w=s.weather.current;parts.push({title:v20Text('补充天气参数','Additional weather variables'),text:[['体感温度','apparent_temperature','°C'],['相对湿度','relative_humidity_2m','%'],['阵风','wind_gusts_10m','m/s'],['风向','wind_direction_10m','°'],['地面气压','surface_pressure','hPa'],['云量','cloud_cover','%']].map(([label,k,u])=>`${v20En()?v18English(label):label}: ${v25Num(w[k])===null?'—':w[k]+' '+(s.weather.current_units?.[k]||u)}`).join('\n')})}return parts};
